let theme = { colour: "blue" };
const button = Object.create(theme);
const link = Object.create(button);

theme.colour = "red";
theme = { colour: "green" };
theme.size = "large";

console.log(button.colour);
console.log(link.colour, link.size);
console.log(Object.getPrototypeOf(button) === theme);
console.log(Object.getPrototypeOf(link) === button);
